284→            >
285→              <svg
286→                viewBox="0 0 24 24"
287→                style={{
288→                  width: '17px',
289→                  height: '17px'
290→                }}
291→              >
292→                <path
293→                  d="M20 2H4C2.9 2 2 2.9 2 4v12c0 1.1.9 2 2 2h2v4l5-4h9c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"
294→                  fill={textColor}
295→                />
296→              </svg>
297→            </button>
298→          </div>
299→
300→          {/* Mobile: Chat + Hamburger - 44px min touch targets */}
301→          {/* Single-click: open chatbot | Double-click: reveal Tools overlay (Easter Egg) */}
302→          <div className="flex md:hidden items-center gap-3">
303→            <button
304→              onClick={handleChatbotClick}
305→              className="nav-link nav-item-shift transition-opacity duration-400"
306→              aria-label="Ask about Joe"
307→              style={{
308→                minWidth: '44px',
309→                minHeight: '44px',
310→                display: 'flex',
