  1→'use client';
  2→
  3→import { useState, useEffect, useRef, useMemo } from 'react';
  4→import { HeroReel } from '@/components/HeroReel';
  5→import { LadderGrid } from '@/components/LadderGrid';
  6→import { usePerception } from '@/lib/perception/context';
  7→import { projects, projectsBySlug } from '@/lib/projects';
  8→import { ProjectAdapter } from '@/lib/perception/adapter';
  9→import { useIsMobile } from '@/lib/hooks/useIsMobile';
 10→import { usePrefersReducedMotion } from '@/lib/hooks/usePrefersReducedMotion';
 11→
 12→// Hoisted static styles — avoids creating new objects on every render
 13→const scrollIndicatorTextStyle = {
 14→  color: 'var(--text-secondary)',
 15→  fontFamily: 'var(--font-display)',
 16→  fontSize: '11px',
 17→  fontWeight: 600,
 18→  letterSpacing: '0.04em',
 19→  textTransform: 'uppercase' as const,
 20→  marginTop: '8px'
 21→};
 22→
 23→const gradientOverlayStyle = {
 24→  height: '250px',
 25→  background: 'linear-gradient(to bottom, var(--background) 0%, transparent 100%)',
 26→  zIndex: 95,
 27→  opacity: 0
 28→};
 29→
 30→const heroSectionStyle = {
 31→  maxWidth: 'var(--max-content-width)',
 32→  paddingLeft: 'var(--side-padding)',
 33→  paddingRight: 'var(--side-padding)',
 34→  paddingTop: 'clamp(102px, 10.2vw + 34px, 170px)',
 35→  paddingBottom: 'clamp(102px, 10.2vw + 34px, 170px)',
 36→};
 37→
 38→const heroTextWrapperStyle = { maxWidth: '900px' };
 39→
 40→const gridSectionStyle = {
 41→  maxWidth: 'var(--max-content-width)',
 42→  paddingLeft: 'var(--side-padding)',
 43→  paddingRight: 'var(--side-padding)',
 44→  paddingBottom: 'var(--space-lg)',
 45→};
 46→
 47→type FilterKey = 'all' | 'film' | 'product' | 'musicvideo';
 48→
 49→const FILTERS: { key: FilterKey; label: string }[] = [
 50→  { key: 'all', label: 'All' },
 51→  { key: 'film', label: 'Film' },
 52→  { key: 'product', label: 'Commercial' },
 53→  { key: 'musicvideo', label: 'Music Video' },
 54→];
 55→
 56→export default function HomePage() {
 57→  // Get perception state from context (sensor runs in PerceptionLayer)
 58→  const { archetype, confidence } = usePerception();
 59→
 60→  const { isMobile } = useIsMobile();
 61→  const prefersReducedMotion = usePrefersReducedMotion();
 62→
 63→  const [introVisible, setIntroVisible] = useState(false);
 64→  const [activeFilter, setActiveFilter] = useState<FilterKey>('all');
 65→
 66→  // Refs for scroll-driven DOM updates (no re-renders on scroll)
 67→  const scrollIndicatorRef = useRef<HTMLDivElement>(null);
 68→  const introTextRef = useRef<HTMLElement>(null);
 69→  const gradientOverlayRef = useRef<HTMLDivElement>(null);
 70→
 71→  // Hero height based on device - matches HeroReel component
 72→  const heroHeight = isMobile ? '50vh' : '70vh';
 73→  const heroHeightMultiplier = isMobile ? 0.5 : 0.7;
 74→
 75→  // Trigger intro animation on mount
 76→  useEffect(() => {
 77→    const timer = setTimeout(() => setIntroVisible(true), 100);
 78→    return () => clearTimeout(timer);
 79→  }, []);
 80→
 81→  // Listen for chatbot open/close via custom event (replaces MutationObserver)
 82→  useEffect(() => {
 83→    const scrollIndicator = scrollIndicatorRef.current;
 84→    if (!scrollIndicator) return;
 85→
 86→    const observer = new MutationObserver(() => {
 87→      const isOpen = document.body.hasAttribute('data-chatbot-open');
 88→      if (scrollIndicator) {
 89→        scrollIndicator.style.opacity = isOpen ? '0' : scrollIndicator.dataset.scrollOpacity || '1';
 90→        scrollIndicator.style.pointerEvents = isOpen ? 'none' : 'auto';
 91→      }
 92→    });
 93→
 94→    observer.observe(document.body, { attributes: true, attributeFilter: ['data-chatbot-open'] });
 95→    return () => observer.disconnect();
 96→  }, []);
 97→
 98→  // Scroll-driven opacity updates via direct DOM manipulation (no React re-renders)
 99→  useEffect(() => {
100→    const handleScroll = () => {
101→      const scrollY = window.scrollY;
102→
103→      // Fade out scroll indicator between 0-300px scroll
104→      const scrollIndicatorOp = Math.max(0, 1 - (scrollY / 300));
105→      if (scrollIndicatorRef.current) {
106→        scrollIndicatorRef.current.dataset.scrollOpacity = String(scrollIndicatorOp);
107→        // Only update DOM if chatbot isn't overriding
108→        if (!document.body.hasAttribute('data-chatbot-open')) {
109→          scrollIndicatorRef.current.style.opacity = String(scrollIndicatorOp);
110→          scrollIndicatorRef.current.style.pointerEvents = scrollIndicatorOp === 0 ? 'none' : 'auto';
111→        }
112→      }
113→
114→      // Fade out intro text right before it overlaps navigation
115→      const fadeStart = 600;
116→      const fadeEnd = 800;
117→      let introOp = 1;
118→      if (scrollY > fadeStart) {
119→        introOp = Math.max(0, 1 - ((scrollY - fadeStart) / (fadeEnd - fadeStart)));
120→      }
121→      if (introTextRef.current) {
122→        introTextRef.current.style.opacity = String(introOp);
123→      }
124→
125→      // Fade gradient overlay for content scrolling under navigation
126→      const currentHeroHeight = window.innerHeight * heroHeightMultiplier;
127→      const contentTopPosition = currentHeroHeight - scrollY;
128→      const navHeight = 200;
129→      let mainTopOp = 1;
130→      if (contentTopPosition < navHeight) {
131→        const fadeDistance = 150;
132→        const distanceIntoNav = navHeight - contentTopPosition;
133→        mainTopOp = Math.max(0, 1 - (distanceIntoNav / fadeDistance));
134→      }
135→      if (gradientOverlayRef.current) {
136→        gradientOverlayRef.current.style.opacity = mainTopOp < 1 ? String((1 - mainTopOp) * 0.95) : '0';
137→      }
138→    };
139→
140→    window.addEventListener('scroll', handleScroll, { passive: true });
141→    return () => window.removeEventListener('scroll', handleScroll);
142→  }, [heroHeightMultiplier]);
143→
144→  // Find General Reel for hero (O(1) Map lookup)
145→  const heroProject = projectsBySlug.get('general-reel');
146→
147→  // Hero statement - authentic, consistent regardless of mode
148→  const heroStatement = "Sixteen years. Feature films, commercials, real-time engines—each frame a problem of light solved in pixels. This is the work.";
149→
