input.new_string:
{FILTERS.map(({ key, label }) => {
  const count = key === 'all'
    ? projects.length
    : projects.filter(p => p.workTypes?.includes(key)).length;
  return (
    <button
      key={key}
      onClick={() => setActiveFilter(key)}
      style={{
        color: activeFilter === key ? 'var(--text-primary)' : 'var(--text-dim)',
        fontFamily: 'var(--font-display)',
        fontWeight: 500,
        fontSize: '11px',
        letterSpacing: '0.12em',
        textTransform: 'uppercase',
        background: 'none',
        padding: '10px 0',
        minHeight: '44px',
        borderBottom: activeFilter === key ? '1px solid var(--text-primary)' : '1px solid transparent',
        transition: 'color var(--transition-base), border-color var(--transition-base)',
        cursor: 'pointer'
      }}
    >
      {label} <span style={{ color: 'var(--text-dim)' }}>({count})</span>
    </button>
  );
})}
